// Which test catches which wrong rule of the flow (ADR 0029, "The tests against wrong rules"), of the picture of the
// tubes (ADR 0034), of an agent under a painted wall (ADR 0038), of the cut and a wall while growth runs (ADR 0039) and
// of respawn while the cut is held (ADR 0041), of the repellent source of the Jones model (ADR 0044), of the mean over a window above 3 × 3 (ADR 0046), of the
// Electrode tool (ADR 0047), of Light stops growth (ADR 0050), of the rule that no child is born onto starved ground
// (ADR 0053), of the mark that a starved tube leaves (ADR 0054), of the slime field, its brush and its picture
// (ADR 0055), of the amount of slime and the film that the picture draws from it (ADR 0057), of the outlines and
// the picture of the electrodes (ADR 0058), of the black level below the plasm (ADR 0062) and of the white level above it (ADR 0090), of the density when the
// rule of one agent per cell goes on (ADR 0063), of the start spot of a scene (ADR 0066), of the forms of a GPU for
// the growth front in the prototype on the CPU (ADR 0067), of the territory of each strain (ADR 0068), of the levers
// of the crown: the flow over 8 neighbours, the base conductance and the flux to the front (ADR 0086), and of the
// avoidance of slime as settings: the weight on slime and the reach to fresh ground (ADR 0088). The script
// puts one wrong rule at a time into a source file of the app,
// runs the GPU tests of the flow, of the picture or of the agents on the backend of that file, and puts the file back.
// A wrong rule of the food sites on the CPU (decision 17, sites.ts) runs the unit tests of its file, and so does one of
// the engine, the sweep, the link or the tool for painted slime. Every wrong rule must fail at least one test.
// Usage: node --import ./research/flow/register.mjs research/flow/engine/mutate.ts [W1 F3 ...]
// It changes files below src/ while it runs, and it writes each one back as it was. It stops if a file has changed
// since the mutations were written: then the text of a mutation no longer fits. With the argument `check` it only
// checks that the text of every right rule is once in its file, and changes no file.
